// Create a global loot modifier
public class MyLootModifier extends LootModifier {
    public MyLootModifier(ICondition[] conditions) {
        super(conditions);
    }

    @Override
    protected List<ItemStack> doApply(List<ItemStack> generatedLoot, LootContext context) {
        // Modify the loot
        for (ItemStack stack : generatedLoot) {
            if (stack.getItem() == Items.DIAMOND) {
                stack.grow(1); // Double diamonds
            }
        }
        return generatedLoot;
    }

    public static class Serializer extends GlobalLootModifierSerializer<MyLootModifier> {
        @Override
        public MyLootModifier m_6754_(JsonObject json, IFunction<LootContext, Boolean>[] conditions) {
            return new MyLootModifier(conditions);
        }

        @Override
        public void m_6757_(JsonObject json, MyLootModifier modifier) {
            // Serialize
        }
    }
}

// Register in data generator
private static final RegistryObject<GlobalLootModifierSerializer<?>> MY_MODIFIER = 
    LOOT_MODIFIERS.register("my_modifier", MyLootModifier.Serializer::new);
